```{.r .cell-code}
# ── D2 pooled test (Li, Meng, Raghunathan & Rubin 1991, Stat. Sin. 1:65-92) ─
#
# Per-imputation Wald chi-squared statistics W_1,...,W_M for k restrictions
# are pooled as:
#
#   W̄  = mean(W_m)
#   b   = var(W_m)
#   r2  = (1 + 1/M) * b / (2k)      # between-imputation variance relative
#                                    # to chi2(k) null variance = 2k
#   D2  = (W̄/k - r2) / (1 + r2)    ~ F(k, v2)
#   v2  = (M - 1) * (1 + 1/r2)²
#
# When r2 → 0 (no MI uncertainty), v2 → ∞ and D2 ≈ chi2(k)/k (standard).
# When r2 → ∞ (MI dominates), v2 → M - 1 (dominated by imputation variance).

d2_test <- function(chi2_vals, k) {
  M    <- length(chi2_vals)
  Wbar <- mean(chi2_vals)
  b    <- var(chi2_vals)

  r2 <- (1 + 1/M) * b / (2 * k)
  D2 <- (Wbar / k - r2) / (1 + r2)

  v2 <- if (r2 < .Machine$double.eps * 100) Inf else (M - 1) * (1 + 1/r2)^2
  p  <- pf(D2, df1 = k, df2 = v2, lower.tail = FALSE)

  tibble(D2 = D2, df1 = k, df2 = v2, p.value = p,
         r2 = r2, chi2_bar = Wbar, chi2_var = b, M = M)
}

# Per-imputation Wald chi-squared for H0: m_DEMOC3 = m_PCGTHOU = m_PERCHPOP = 0
mundlak_terms <- c("m_DEMOC3", "m_PCGTHOU", "m_PERCHPOP")
k             <- length(mundlak_terms)

chi2_vals <- vapply(a_mundlak$imputations, function(d) {
  fit  <- plm(mundlak_formula, data = d,
              index = c("IDORIGIN", "YEAR"), model = "random")
  bvec <- coef(fit)[mundlak_terms]
  Vmat <- vcov(fit)[mundlak_terms, mundlak_terms]
  as.numeric(t(bvec) %*% solve(Vmat) %*% bvec)
}, numeric(1))

cat(sprintf(
  "Per-imputation Wald chi2(%d): mean = %.3f  SD = %.3f  range = [%.3f, %.3f]\n",
  k, mean(chi2_vals), sd(chi2_vals), min(chi2_vals), max(chi2_vals)
))
